{
  "status": "STABLE",
  "core_findings": [
    "Sampled training-pair ranking is strong across all four categories: negatives beat positives in 1.4–4.75% of valid pairs. Embedding scores of 0.5056–0.5121 indicate near-zero mean cosine alignment, without evidence of directional collapse.",
    "Composite deletion, final-item deletion, and context deletion with the final item preserved all reduce descriptive pairwise wins across 1,280 eligible rows per category. Leading-padding GRU updates confound these interventions, so recency conclusions are withheld."
  ],
  "key_implications": [
    "The model separates most sampled training positives from negatives; these diagnostics do not establish validation HR@10 or improvement.",
    "Repeated-call and batch-order checks agree exactly, but shortened-history comparisons are sensitive to padding execution.",
    "Anonymous loader aggregates may overweight frequent users, and user-level uncertainty intervals are unavailable."
  ],
  "evidence": {
    "headline_metrics": {
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": 0.0475,
      "CDs_and_Vinyl:pos_neg_neg_beats_pos_rate": 0.014,
      "Electronics:embedding_collapse_score": 0.5121,
      "CDs_and_Vinyl:history_sensitivity.execution_audit.unpadded_max_abs_score_difference": 2.381481170654297
    },
    "brief_metric_read": {
      "training_pair_errors": "Movies has the highest sampled error rate; CDs has the lowest.",
      "embedding_geometry": "Scores near 0.5 reflect near-zero mean cosine, not recommendation diversity.",
      "unpadded_replay": "Substantial score differences support the reported padding confound."
    }
  }
}
